1	export type Cell = [number, number];
2	
3	type CellKey = string;
4	
5	const keyOf = ([x, y]: Cell): CellKey => `${x},${y}`;
6	
7	const cellOf = (key: CellKey): Cell => {
8	  const [x, y] = key.split(",").map(Number);
9	  return [x, y];
10	};
11	
12	function neighborsOf([x, y]: Cell): Cell[] {
13	  return [-1, 0, 1].flatMap((dx) =>
14	    [-1, 0, 1]
15	      .filter((dy) => !(dx === 0 && dy === 0))
16	      .map((dy): Cell => [x + dx, y + dy]),
17	  );
18	}
19	
20	function countLiveNeighbors(cell: Cell, liveCells: Set<CellKey>): number {
21	  return neighborsOf(cell).filter((neighbor) => liveCells.has(keyOf(neighbor)))
22	    .length;
23	}
24	
25	function cellsToEvaluate(cells: Cell[]): Cell[] {
26	  const keys = cells.flatMap((cell) => [
27	    keyOf(cell),
28	    ...neighborsOf(cell).map(keyOf),
29	  ]);
30	  return [...new Set(keys)].map(cellOf);
31	}
32	
33	function isAliveNextGeneration(cell: Cell, liveCells: Set<CellKey>): boolean {
34	  const liveNeighborCount = countLiveNeighbors(cell, liveCells);
35	  if (liveCells.has(keyOf(cell))) {
36	    return liveNeighborCount === 2 || liveNeighborCount === 3;
37	  }
38	  return liveNeighborCount === 3;
39	}
40	
41	export function nextGeneration(cells: Cell[]): Cell[] {
42	  const liveCells = new Set(cells.map(keyOf));
43	  return cellsToEvaluate(cells).filter((cell) =>
44	    isAliveNextGeneration(cell, liveCells),
45	  );
46	}
